#!/usr/bin/env Rscript
# UMAP dimensional reduction visualizations.
# Requires: src/final_figures/output/umap_coords_metadata.csv
#           (generated by 00_extract_h5ad_data.py)
#
# Outputs (src/final_figures/output/figures/):
#   umap_overview.pdf       – 4-panel: cluster, age, condition, area
#   umap_by_condition.pdf   – faceted by age × condition

suppressPackageStartupMessages({
  library(ggplot2)
  library(dplyr)
  library(patchwork)
  library(RColorBrewer)
  library(stringr)
})

BASE    <- "/dfs9/ucightf-lab/projects/ChatS/251006_0925Bio-06_ChatS_xenium"
DATADIR <- file.path(BASE, "src/final_figures/output")
OUTDIR  <- file.path(BASE, "src/final_figures/output/figures")
dir.create(OUTDIR, recursive = TRUE, showWarnings = FALSE)

umap_file <- file.path(DATADIR, "umap_coords_metadata.csv")
if (!file.exists(umap_file)) {
  stop("Run 00_extract_h5ad_data.py first to generate: ", umap_file)
}

cells <- read.csv(umap_file)
cells$leiden_harmony <- factor(cells$leiden_harmony,
                                levels = as.character(sort(unique(as.integer(
                                  cells$leiden_harmony
                                )))))

# ── Color palettes ─────────────────────────────────────────────────────────────
n_clusters   <- nlevels(cells$leiden_harmony)
cluster_cols <- setNames(
  colorRampPalette(c(
    brewer.pal(12, "Paired"), brewer.pal(8, "Set2")
  ))(n_clusters),
  levels(cells$leiden_harmony)
)

age_cols  <- c(adult = "#2166AC", aged = "#D73027")
cond_cols <- c(control = "#66C2A5", heatstress = "#FC8D62")
area_cols <- c(area_1 = "#7B2D8B", area_2 = "#E6932A",
               area_3 = "#2E8B57", area_4 = "#C0392B")

# ── Base theme ─────────────────────────────────────────────────────────────────
theme_umap <- function(legend_pos = "right") {
  theme_void(base_size = 10) +
    theme(
      legend.position = legend_pos,
      legend.title    = element_text(size = 9, face = "bold"),
      legend.text     = element_text(size = 8),
      legend.key.size = unit(3, "mm"),
      plot.title      = element_text(size = 11, face = "bold", hjust = 0.5),
      plot.margin     = margin(4, 4, 4, 4)
    )
}

PT_SIZE <- 0.15
PT_ALPHA <- 0.4

# ── Panel A: colored by Leiden cluster ────────────────────────────────────────
p_cluster <- ggplot(cells %>% arrange(sample(nrow(cells))),
                    aes(UMAP1, UMAP2, color = leiden_harmony)) +
  geom_point(size = PT_SIZE, alpha = PT_ALPHA) +
  scale_color_manual(values = cluster_cols, name = "Cluster") +
  guides(color = guide_legend(override.aes = list(size = 3, alpha = 1),
                               ncol = 2)) +
  labs(title = "Leiden Clusters") +
  theme_umap()

# ── Panel B: colored by age ────────────────────────────────────────────────────
p_age <- ggplot(cells %>% arrange(age),
                aes(UMAP1, UMAP2, color = age)) +
  geom_point(size = PT_SIZE, alpha = PT_ALPHA) +
  scale_color_manual(values = age_cols, name = "Age") +
  guides(color = guide_legend(override.aes = list(size = 3, alpha = 1))) +
  labs(title = "Age") +
  theme_umap()

# ── Panel C: colored by condition ─────────────────────────────────────────────
p_cond <- ggplot(cells %>% arrange(condition),
                 aes(UMAP1, UMAP2, color = condition)) +
  geom_point(size = PT_SIZE, alpha = PT_ALPHA) +
  scale_color_manual(values = cond_cols, name = "Condition") +
  guides(color = guide_legend(override.aes = list(size = 3, alpha = 1))) +
  labs(title = "Condition") +
  theme_umap()

# ── Panel D: colored by brain area ────────────────────────────────────────────
if ("area" %in% names(cells)) {
  p_area <- ggplot(cells %>% arrange(area),
                   aes(UMAP1, UMAP2, color = area)) +
    geom_point(size = PT_SIZE, alpha = PT_ALPHA) +
    scale_color_manual(values = area_cols, name = "Brain Area") +
    guides(color = guide_legend(override.aes = list(size = 3, alpha = 1))) +
    labs(title = "Brain Area") +
    theme_umap()
} else {
  p_area <- ggplot() + theme_void() +
    annotate("text", x = 0.5, y = 0.5, label = "area not available")
}

# ── Overview PDF (2×2) ─────────────────────────────────────────────────────────
overview <- (p_cluster | p_age) / (p_cond | p_area) +
  plot_annotation(
    title = "UMAP – Harmony-integrated Xenium data",
    theme = theme(plot.title = element_text(size = 14, face = "bold",
                                             hjust = 0.5))
  )

pdf(file.path(OUTDIR, "umap_overview.pdf"), width = 14, height = 11)
print(overview)
invisible(dev.off())
message("Saved: umap_overview.pdf")

# ── Faceted UMAP: age × condition ─────────────────────────────────────────────
cells$facet_label <- paste0(str_to_title(cells$age), "\n",
                             str_to_title(cells$condition))
facet_order <- c("Adult\nControl", "Adult\nHeatstress",
                 "Aged\nControl",  "Aged\nHeatstress")
cells$facet_label <- factor(cells$facet_label,
                              levels = intersect(facet_order,
                                                 unique(cells$facet_label)))

p_facet <- ggplot(cells %>% arrange(sample(nrow(cells))),
                  aes(UMAP1, UMAP2, color = leiden_harmony)) +
  geom_point(size = 0.1, alpha = 0.3) +
  facet_wrap(~facet_label, nrow = 2) +
  scale_color_manual(values = cluster_cols, name = "Cluster") +
  guides(color = guide_legend(override.aes = list(size = 2.5, alpha = 1),
                               ncol = 3)) +
  labs(title = "UMAP by Age × Condition") +
  theme_umap("right") +
  theme(
    strip.text       = element_text(size = 10, face = "bold"),
    strip.background = element_rect(fill = "grey20", color = NA),
    panel.spacing    = unit(3, "mm")
  )

pdf(file.path(OUTDIR, "umap_by_condition.pdf"), width = 14, height = 9)
print(p_facet)
invisible(dev.off())
message("Saved: umap_by_condition.pdf")
